include 'includes/session.php';include 'includes/functions.php';if(empty($_SESSION['userId'])){header('Location: login.php');exit;}$id=(int)($_GET['id']??0);$s=$conn->prepare('SELECT c.*,m.FullName,m.Phone,m.Email,COALESCE(SUM(p.amount),0) paid FROM charges c JOIN members m ON m.id=c.member_id LEFT JOIN payments p ON p.charge_id=c.id WHERE c.id=? GROUP BY c.id');$s->execute([$id]);$c=$s->fetch();if(!$c){http_response_code(404);exit('Invoice not found.');}$balance=(float)$c['Price']-(float)$c['paid'];
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Invoice <?=escape((string)$c['id'])?></title><link rel="stylesheet" href="assets/vendor/css/core.css"><style>@media print{.no-print{display:none}.invoice{box-shadow:none!important}}body{background:#f5f5f9}.invoice{max-width:760px;margin:40px auto}</style></head><body><div class="card invoice"><div class="card-body p-5"><div class="d-flex justify-content-between"><div><h2>Reza GYM</h2><p>Membership Invoice</p></div><div class="text-end"><h4>INV-<?=str_pad((string)$c['id'],6,'0',STR_PAD_LEFT)?></h4><p><?=escape($c['date'])?></p></div></div><hr><h6>Bill To</h6><h4><?=escape($c['FullName'])?></h4><p><?=escape($c['Phone'])?> · <?=escape($c['Email'])?></p><table class="table mt-4"><thead><tr><th>Description</th><th>Billing Month</th><th class="text-end">Amount</th></tr></thead><tbody><tr><td><?=escape($c['remarks'])?></td><td><?=escape($c['billing_month'])?></td><td class="text-end"><?=money($c['Price'])?></td></tr></tbody></table><div class="ms-auto" style="max-width:320px"><div class="d-flex justify-content-between"><span>Paid</span><span><?=money($c['paid'])?></span></div><div class="d-flex justify-content-between border-top pt-2 mt-2"><strong>Balance Due</strong><strong><?=money($balance)?></strong></div></div><p class="mt-5"><span class="badge <?= $balance<=0?'bg-success':'bg-warning'?>"><?=escape($c['status'])?></span></p><div class="text-center no-print"><button onclick="print()" class="btn btn-primary">Print / Save PDF</button><button onclick="history.back()" class="btn btn-label-secondary">Back</button></div></div></div></body></html>
